      "category": "detection",
      "trigger": "When identifying specific parenchymal patterns on high-resolution CT to support a diagnosis of histiocytic lung disease.",
      "steps": [
        "Scan the lung windows for a reticulonodular pattern characterized by the coexistence of small centrilobular nodules and cystic spaces.",
        "Verify the presence of 'bizarre' or stellate-shaped cysts rather than simple spherical lucencies.",
        "Confirm the absence of significant fibrosis or honeycombing in the subpleural regions of the lower lobes to rule out idiopathic pulmonary fibrosis."
      ]
    }
